	Name string
	P95  float64
}{
	{"building image", 154},
	{"pushing image", 151},
	{"shifting 10% of traffic", 148},
	{"shifting 50% of traffic", 121},
	{"shifting 100% of traffic", 96},
	{"checking health", 92},
}

